/** One allowed additional quantity (a count) with its penalty and notation. */
export interface AQValue {
  /** Numeric count (e.g. 1.25). */
  readonly value: number;
  /** Canonical notation used in files and display (`1+1/4`). */
  readonly notation: string;
  /** 0 = perfectly clean, 1 = very awkward (docs/recipe_scaling_algorithm.md §3.2). */
  readonly penalty: number;
}

